"""Five original BDC worksheets; inputs remain in the reader's browser."""
from pathlib import Path
from education import E, shell, section_head

SOURCES = [
    ('Investor.gov: publicly traded BDCs', 'https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/publicly-traded-business-development-companies-bdcs-investor-bulletin'),
    ('SEC EDGAR: find the original filing', 'https://www.sec.gov/edgar/search/'),
    ('Issuer filing: PIK recognition and non-accrual accounting policy (definitions, not example data)', 'https://www.sec.gov/Archives/edgar/data/1859919/000185991925000013/bdc-20241231.htm'),
]

TOOLS = [
    dict(slug='calculator-bdc-nii-pik',kind='nii',title='BDC NII, PIK & distribution worksheet',
         description='Separate regular and total common-distribution coverage, then trace a simple PIK-deduction sensitivity on a consistent period and unit basis.',
         inputs=[('nii','Reported net investment income','120'),('pik','PIK income included in that NII','18'),('tii','Total investment income (optional)','180'),('regular','Regular common distributions','100'),('supplemental','Supplemental common distributions','10'),('special','Special common distributions','5')],
         question='Does the reported income cover the regular distribution and the entire distribution on the same basis? What changes if a stated portion of recognized PIK is deducted as a simple sensitivity?',
         definitions='Net investment income is an accounting income measure after applicable investment expenses; it is not a cash-flow statement. Payment-in-kind income can enter recognized income before cash is received. Use the amount included in the chosen NII, rather than the balance of PIK-bearing investments. Separate ordinary, supplemental and special common distributions instead of comparing earnings only with the smallest visible payment.',
         formula='Total distributions = regular + supplemental + special. Regular coverage = NII / regular distributions. Total coverage = NII / total distributions. PIK/TII = PIK income / total investment income. PIK/NII is interpreted only if NII is positive. At deduction fraction f, sensitivity income = NII − PIK × f; coverage divides this hypothetical income by the matching distribution.',
         example='Synthetic quarter, USD million: NII 120, included PIK 18, total investment income 180, regular distribution 100, supplemental 10 and special 5. Total distributions are 115. Regular coverage is 1.2000× and total coverage is 1.0435×. PIK/TII is 10.0000%, while PIK/NII is 15.0000%. At 25%/50%/100% PIK deductions, income is 115.5/111/102 and total coverage is 1.0043×/0.9652×/0.8870×. These are deliberately hypothetical inputs, not a company record.',
         locate='Start with the statement of operations for NII and total investment income. Follow the investment-income accounting policy and PIK disclosure to establish what was recognized during the exact period. Find common distributions in the changes in net assets, distribution note and declarations. A cash-flow statement may show cash paid on a different timetable. Check declared versus paid basis and distinguish common from preferred distributions before copying values.',
         interpretation='Regular coverage and total coverage are both useful because a supplemental distribution changes the denominator. Neither ratio establishes the tax character, sustainability or timing of cash payments. A negative NII produces signed negative coverage rather than a hidden zero. If supplemental or special distributions are unknown, leave them blank: total coverage remains undefined while regular coverage can still be calculated. An explicit zero is a separate user assumption.',
         limits='Deducting PIK is a simple sensitivity, not cash earnings, operating cash flow or cash available for distributions. It holds expenses, incentive fees, taxes, collections and other noncash items constant. The 100% column is not a default or loss forecast. Total-amount mode avoids silently dividing PIK by current shares and comparing it with NII calculated using weighted-average shares. Reported and issuer-adjusted NII cannot be mixed. No recommendation, safety score or tax distribution test is generated.',
         faq=[('Why is an unknown supplement not zero?','Zero asserts there was no amount. A blank means the amount has not been established; the total cannot be completed without an assumption.'),('Can I use a paid distribution?','Yes, select paid and apply that basis to every distribution input. Paid cash can relate to an earlier declaration, so the time comparison needs explanation.')]),
    dict(slug='calculator-bdc-pik-ratios',kind='pik',title='BDC PIK income ratios',
         description='Keep PIK as a share of total investment income separate from PIK relative to net investment income.',
         inputs=[('nii','Reported net investment income','120'),('pik','PIK income included in NII','18'),('tii','Total investment income','180')],
         question='How large is recognized PIK compared with investment revenue, and how large is the same amount compared with the narrower net-income base?',
         definitions='PIK is a form of noncash income recognition whose treatment must be read in the issuer accounting policy. The balance of a PIK loan is not the same as PIK income for the period. Total investment income is a revenue measure; NII is after investment expenses. An identical numerator therefore produces two different ratios with different meanings. Fees, original-issue discount accretion and noncash dividends may be disclosed separately and should not be silently reclassified as PIK.',
         formula='PIK share of total investment income = included PIK income / total investment income × 100. PIK relative to NII = included PIK income / NII × 100, interpreted only when NII > 0. These are separate calculations, not interchangeable definitions of a cash-conversion ratio.',
         example='Synthetic quarter, USD million: recognized PIK is 18, total investment income is 180 and NII is 120. PIK/TII = 18 / 180 = 10%. PIK/NII = 18 / 120 = 15%. If NII falls to 60 while the other inputs stay unchanged, PIK/TII remains 10% and PIK/NII rises to 30%. The second increase can reflect expense pressure rather than new PIK recognition. If NII is −10, the worksheet retains that entered loss in the input record but does not label −180% as a meaningful income share.',
         locate='Read the income statement and the investment-income recognition note together. Identify whether the issuer separates PIK interest, noncash preferred dividends and fee accretion. Search the filing for both “payment-in-kind” and “non-accrual”; an issuer may reverse or stop accrual when collection is doubtful. Record the note and page, period, amount and whether the value is gross or net of reversals. Do not infer a missing flow from a year-end investment balance.',
         interpretation='A large PIK ratio calls for an explanation of contractual terms, borrower performance and collection history. It does not by itself establish that income is fictitious or uncollectible. Compare like periods and definitions before describing a trend. A ratio can rise because its denominator shrinks. The worksheet intentionally shows both denominators so the reader can identify this effect rather than relying on a single unlabeled “PIK percentage.”',
         limits='The worksheet does not value loans, estimate recoveries, model cash collections or reconcile taxable income. Negative PIK reversals cannot be entered as ordinary positive PIK income here; analyze such a period separately with the original reconciliation. Missing total investment income disables only PIK/TII. Missing NII disables PIK/NII. There is no market-data feed and no ranking of companies.',
         faq=[('Does 10% PIK mean 90% cash earnings?','No. Other noncash items, expenses and working-capital movements remain. This is an income-composition ratio.'),('Is PIK always a sign of default?','No. Contractual PIK and distressed payment amendments require context. Recognition and collectibility policies must be checked in the filing.')]),
    dict(slug='calculator-bdc-non-accrual',kind='non-accrual',title='BDC non-accrual: cost versus fair value',
         description='Compare two non-accrual percentages without mixing their investment populations or valuation bases.',
         inputs=[('nonAccrualCost','Non-accrual investment cost','50'),('portfolioCost','Matching total investment cost','1000'),('nonAccrualFv','Non-accrual investment fair value','20'),('portfolioFv','Matching total investment fair value','950')],
         question='How much of a consistently defined investment population is on non-accrual at cost, and how much does it represent at fair value?',
         definitions='Non-accrual is an accounting treatment for income recognition, governed by the issuer policy and collectibility assessment. The investment need not have a fair value of zero. Cost and fair value give distinct views: cost retains the investment basis while fair value reflects the valuation used at the reporting date. A percentage of total debt investments is not directly comparable with a percentage of all investments, including equity.',
         formula='Non-accrual at cost = non-accrual investment cost / matching portfolio cost × 100. Non-accrual at fair value = non-accrual fair value / matching portfolio fair value × 100. Non-accrual FV/cost = non-accrual fair value / non-accrual cost × 100. Each denominator must use the same population as its numerator.',
         example='Synthetic point-in-time snapshot, USD million: non-accrual cost 50 within total matching cost 1,000 gives 5.0000%. Non-accrual fair value 20 within total matching fair value 950 gives 2.1053%. The non-accrual assets are marked at 40.0000% of their cost. If they are written down further, the fair-value percentage may fall even if the cost exposure does not improve. That is why a lower fair-value percentage is not automatically evidence of better credit performance.',
         locate='Start with the schedule of investments and footnotes that identify non-accrual positions. Reconcile the disclosed totals to the portfolio population used by management. Read the valuation note and non-accrual accounting policy, including whether uncapitalized accrued interest is reversed. Capture the same as-of date for all four values. If only total-debt percentages are disclosed, do not use an all-investment denominator to reconstruct an apparently comparable number.',
         interpretation='Read the two percentages side by side. A wide gap can reflect valuations below cost, while changes in portfolio size also move each denominator. A zero fair-value amount with positive cost is retained rather than dropped as a missing record. Neither percentage estimates the probability of default or the eventual recovery. Verify whether a restructuring or sale changed membership in the non-accrual population between dates.',
         limits='This is a descriptive snapshot, not a credit model. It does not distinguish first-lien from subordinated claims, assess collateral, predict exits from non-accrual or convert fair-value marks into realized losses. Total portfolio values must be positive for ratios to exist. A non-accrual numerator above its corresponding total is rejected. Do not compare cost and fair-value amounts from different dates or scopes.',
         faq=[('Why is the fair-value ratio lower?','A position marked below cost contributes less to a fair-value numerator; the two total denominators also differ.'),('Can a reported 0% be treated as an exact zero?','A rounded disclosure may conceal a small amount. Preserve the published precision and the source note rather than inventing an exact amount.')]),
    dict(slug='calculator-bdc-nav-discount',kind='nav',title='BDC price / NAV discount calculator',
         description='Compare a user-entered share price with disclosed common NAV per share while preserving dates and assumptions.',
         inputs=[('price','User-entered market price per common share','18'),('nav','Disclosed common NAV per share','20')],
         question='At the entered price, what premium or discount is implied relative to the entered common NAV per share?',
         definitions='NAV per share represents the common net-asset base divided by the applicable common-share count under the issuer disclosure. The market price is a traded quotation at a different moment. The difference between the two is a valuation relationship, not a promised gain. A BDC invests in loans and other securities, and a disclosed fair-value estimate may differ from a later realization. Use the same share class and currency for both inputs.',
         formula='Price/NAV = entered market price per common share / common NAV per share. Signed premium or discount = (price/NAV − 1) × 100. Price less NAV = entered price − NAV. A negative signed percentage is a discount; a positive value is a premium. Positive NAV is required for the first two ratios.',
         example='Synthetic per-share illustration in USD: an entered price of 18 and common NAV per share of 20 produce price/NAV of 0.9000× and a signed discount of −10.0000%. Price less NAV is −2.0000. If price is 22 with NAV unchanged at 20, the signed result is a +10.0000% premium. This is not the same as the return needed to rise from 18 to 20, which would use 18 as its denominator.',
         locate='Find the common NAV per share in the financial statements, statement of assets and liabilities or financial highlights. Record the reporting date, share class, issuer calculation and any later distribution or issuance affecting comparability. Record the market-price date and source in the price input note. There is no automatic quote service: the reader supplies both values. The common as-of context is an analysis date and must be on or after the reporting period end. NAV is a stock measure at its disclosed balance-sheet snapshot date, not income over the entered period. The market quote can have a different observation date: retain both the NAV snapshot date and the actual quote date in their respective source locators. The analysis date does not make these two observations contemporaneous and does not relabel either as a period-end quote.',
         interpretation='A discount can reflect expected losses, expenses, financing conditions, management incentives, liquidity or the market assessment of the valuation process. It is not an automatic bargain. A premium is not proof of overvaluation. Compare valuation dates and the underlying portfolio rather than treating the ratio as a trading signal. Investor.gov explains that publicly traded BDC prices can be above or below NAV; the calculator only quantifies this relationship for your inputs.',
         limits='No appraisal, target price or expected return is produced. NAV can become stale and the price can move after entry. The tool does not adjust for subsequent distributions, rights issues, stock splits, FX or changes in portfolio value. Zero or negative NAV makes a conventional premium/discount ratio unhelpful and is shown as undefined while the arithmetic price-minus-NAV difference remains visible.',
         faq=[('Is a 20% discount a guaranteed 20% gain?','No. NAV and price can both change, and the discount need not close.'),('Does this tool fetch a current share price?','No. Every figure is entered by the reader; the initial example is synthetic.')]),
    dict(slug='calculator-bdc-leverage',kind='leverage',title='BDC debt / equity worksheet',
         description='Calculate descriptive gross and cash-adjusted debt/equity ratios without claiming statutory asset-coverage compliance.',
         inputs=[('debt','Defined debt amount','800'),('equity','Common equity / common net assets','1000'),('cash','Entered cash for optional adjustment','50')],
         question='How much defined debt is reported relative to common equity, and what changes if the reader separately subtracts entered cash?',
         definitions='Debt/equity is a descriptive relationship between two balance-sheet measures. It is not the same as the statutory asset-coverage calculation applicable to a BDC or a borrowing covenant. Define debt as principal, carrying value or another disclosed measure before entering it. Use common equity rather than silently including preferred capital. State whether subsidiaries, financing vehicles and exempt debt are inside the chosen scope.',
         formula='Gross debt/equity = defined debt / common equity. Cash-adjusted amount = defined debt − entered cash. Cash-adjusted debt/equity = (defined debt − entered cash) / common equity. Ratios require positive common equity. Cash is a separate optional assumption; subtracting it does not repay debt or establish that it is legally available to all creditors.',
         example='Synthetic balance sheet, USD million: defined debt 800, common equity 1,000 and entered cash 50. Gross debt/equity is 0.8000×. Debt less entered cash is 750 and cash-adjusted debt/equity is 0.7500×. If common equity declines to 800 with debt and cash unchanged, the ratios rise to 1.0000× and 0.9375×. No new borrowing is needed for a falling equity denominator to increase these measures.',
         locate='Read the statement of assets and liabilities, borrowing notes and schedule of investments together. Record the debt basis, reporting date, consolidated scope and cash restrictions. Separate preferred stock and other senior claims rather than putting them into common equity. Read the issuer statutory asset-coverage disclosure directly; do not attempt to back-solve compliance from this simplified debt/equity worksheet.',
         interpretation='Both financing transactions and fair-value changes can move the ratio. A cash balance may be restricted, held in a separate entity or required for unsettled investments. Therefore the optional cash adjustment is displayed beside the gross ratio and is never substituted for it. A negative cash-adjusted debt amount can occur when entered cash exceeds debt; that arithmetic outcome is retained without claiming an issuer has no risk.',
         limits='No statutory compliance judgment is made. Applicable asset coverage, preferred claims, SBIC exemptions, subsidiary financing, guarantees, covenants and regulatory definitions need a separate legal and accounting analysis. This tool does not estimate borrowing capacity, rating headroom, interest coverage or dividend limits. Zero or negative common equity is not relabeled as an exceptionally low leverage ratio.',
         faq=[('Is 1.0× debt/equity a statutory pass?','The worksheet does not make that determination. Statutory asset coverage uses a separate definition and instrument treatment.'),('Can cash always be netted?','No. The optional arithmetic adjustment requires a stated assumption about cash scope and availability; it does not alter legal debt.')]),
]


def field(id_, label, value):
    return f'''<div class="calculator-field"><label for="bdc-{id_}">{E(label)}</label><input data-bdc-input type="text" inputmode="decimal" id="bdc-{id_}" name="{id_}" value="{value}" maxlength="64" autocomplete="off" aria-describedby="{id_}-status"><p class="bdc-field-status" id="{id_}-status" data-bdc-status="{id_}" aria-live="polite">Entered scenario amount. Check source and availability below.</p><details><summary>Source and availability</summary><label for="{id_}-availability">Availability</label><select id="{id_}-availability" name="{id_}Availability"><option value="scenario">Entered scenario amount</option><option value="reported">Copied disclosure (not independently verified)</option><option value="not_disclosed">Not disclosed</option><option value="not_found">Not found</option><option value="not_applicable">Not applicable</option></select><p>Blank = not found. Enter 0 only for an explicit zero or a stated zero scenario. Manual input is not verification.</p><label for="{id_}-source">Source URL (HTTPS, optional for a scenario)</label><input type="url" id="{id_}-source" name="{id_}Source"><label for="{id_}-acc">SEC accession (if applicable)</label><input id="{id_}-acc" name="{id_}Accession" maxlength="64"><label for="{id_}-locator">Document location, definition and actual observation date</label><textarea id="{id_}-locator" name="{id_}Locator" rows="2" maxlength="2000"></textarea></details></div>'''


def page(root, tool):
    fields=''.join(field(*item) for item in tool['inputs'])
    src=''.join(f'<li><a href="{E(url)}" target="_blank" rel="noopener">{E(label)} ↗</a></li>' for label,url in SOURCES)
    faq=''.join(f'<details><summary>{E(q)}</summary><p>{E(a)}</p></details>' for q,a in tool['faq'])
    kind=tool['kind']
    lesson={'nii':'nii-coverage','pik':'pik-income','non-accrual':'non-accrual','nav':'nav-discounts','leverage':'leverage-coverage'}[kind]
    reading_class=' bdc-nav-notes' if kind=='nav' else ''
    basis='<p>Inputs are directly entered per-common-share values. No total-amount or weighted-average-share conversion is performed.</p>' if kind=='nav' else '<p>Inputs are total amounts. Do not paste per-share income into an amount field. Use one currency and scale throughout.</p>'
    income_context = '' if kind=='nav' else '''<div><label for="bdc-income-basis">NII definition (applies where used)</label><select id="bdc-income-basis" name="incomeBasis"><option value="reported">Reported NII</option><option value="adjusted">Issuer-adjusted NII — note definition in sources</option></select></div><div><label for="bdc-distribution-basis">Common distributions (applies where used)</label><select id="bdc-distribution-basis" name="distributionBasis"><option value="declared">Declared during the period</option><option value="paid">Paid during the period — timing may differ</option></select></div>'''
    pik_intro='<p data-pik-introduction><strong>PIK means payment-in-kind:</strong> income recognized before cash is received. Enter the PIK income included in net investment income (NII) for the selected period, not the outstanding balance of PIK-bearing investments. Total investment income (TII) is the broader income denominator.</p>' if kind in ('nii','pik') else ''
    body=f'''<div class="wrap breadcrumbs"><a href="/">Home</a><span>/</span><a href="/tools.html">Calculators</a><span>/</span><span aria-current="page">{E(tool['title'])}</span></div>
{section_head('The BDC numbers desk',E(tool['title']),tool['description'])}
<div class="wrap article-meta">By <a href="/about.html#jeong-mo-goo">Jeong-Mo Goo</a> · Published <time datetime="2026-10-18">18 October 2026</time> · Updated <time datetime="2026-10-18">18 October 2026</time></div>
<section class="wrap education-section{reading_class}"><h2>The question to answer.</h2><p>{E(tool['question'])}</p>{pik_intro}<p><strong>Educational scenario, not a forecast or investment recommendation.</strong> All prefilled amounts are synthetic. Editing them creates an unverified user scenario. Calculations stay in this browser tab; no inputs are stored or transmitted.</p></section>
<section class="wrap calculator-layout"><form class="calculator-form" data-bdc-tool="{kind}"><fieldset data-calculator-controls disabled><p class="calculator-loading" data-calculator-loading>Calculator controls unlock when the calculation scripts finish loading. If they stay disabled, reload this page or use the formulas and worked example below.</p><h2>Your assumptions</h2>{basis}<p>The analysis as-of date must be on or after the reporting period end. For balance-sheet stock measures, period fields identify the reporting context, not an averaging interval. Preserve actual snapshot and market-quote dates in each source note.</p><p>Keep every input on the period, basis and unit selected below. Source links are notes for your own audit, not a claim of verification.</p>
<div class="calculator-fields"><div><label for="bdc-start">Common period start</label><input type="date" id="bdc-start" name="periodStart" value="2026-07-01" required></div><div><label for="bdc-end">Common period end</label><input type="date" id="bdc-end" name="periodEnd" value="2026-09-30" required></div><div><label for="bdc-asof">Analysis as-of date (not the quote date)</label><input type="date" id="bdc-asof" name="asOf" value="2026-09-30" required></div><div><label for="bdc-currency">Common currency</label><select id="bdc-currency" name="currency"><option>USD</option><option>EUR</option><option>GBP</option><option>KRW</option></select></div><div><label for="bdc-scale">Common scale</label><select id="bdc-scale" name="scale">{'<option value="one">Per share, currency units</option>' if kind=='nav' else '<option value="million">Millions</option><option value="thousand">Thousands</option><option value="one">Currency units</option>'}</select></div>{income_context}{fields}</div>
<div class="btns"><button class="btn btn-p" type="submit">Calculate →</button><button class="btn btn-s" type="reset">Load synthetic example</button><button class="btn btn-s" type="button" data-bdc-clear>Clear amounts</button><button class="btn btn-s" type="button" data-bdc-print>Print worksheet</button></div><p id="bdc-input-error" data-bdc-error class="calculator-error" role="alert" hidden></p><noscript><p>Interactive calculation needs JavaScript. All definitions, formulas and worked examples below remain readable without it.</p></noscript></fieldset></form>
<div class="calculator-output" role="region" aria-label="BDC worksheet results" aria-live="polite"><h2>Your calculation record.</h2><div data-bdc-result><p>No result yet. Calculation requires the controls to finish loading.</p></div></div></section>
<div class="wrap reading-layout calculator-notes"><aside class="article-toc"><span class="kicker">Read the method</span><ol><li><a href="#definitions">Definitions</a></li><li><a href="#formula">Formula</a></li><li><a href="#example">Synthetic example</a></li><li><a href="#filing-inputs">How to use</a></li><li><a href="#limits">Assumptions and limitations</a></li></ol></aside><article class="lesson-body"><section id="definitions"><h2>Define the inputs before comparing.</h2><p>{E(tool['definitions'])}</p></section><section id="formula"><h2>The calculation.</h2><p>{E(tool['formula'])}</p><p>Formula version bdc-1.0.2. Decimal arithmetic uses 40 significant digits without intermediate display rounding. Arithmetic precision does not increase the accuracy of the source inputs. Display rounds half up to four decimal places; nonzero values smaller than 0.0001 retain five significant digits. Plain decimals are used through 24 fractional places; longer tiny values use scientific notation. Blank or unavailable inputs stay missing; zero denominators produce “Not defined” with a reason.</p></section><section id="example" class="worked-example"><span class="kicker">Synthetic example — not company results</span><h2>Reproduce the arithmetic.</h2><p>{E(tool['example'])}</p></section><section id="filing-inputs"><h2>How to use: find and match the inputs</h2><p>{E(tool['locate'])}</p><p>Record each source URL, accession if applicable, table or note location, original period and scale. Preserve the issuer definition. The source record below each result distinguishes manual entry from review: no reviewer or review date is invented.</p></section><section><h2>Interpret the result with its denominator.</h2><p>{E(tool['interpretation'])}</p></section><section id="limits"><h2>Assumptions and limitations</h2><p>{E(tool['limits'])}</p><p>No automatic currency, share-count, quarter/YTD or adjusted-to-reported conversion occurs. The common context is a user assertion, not evidence that pasted figures match. Check each original disclosure yourself; a manual input is not a verified company result.</p></section><section><h2>Questions worth asking.</h2>{faq}</section><section><h2>Primary sources and corrections.</h2><ul>{src}</ul><p>Sources explain the definitions and disclosure context; the synthetic numbers above do not come from these issuers. See our <a href="/editorial-policy.html">editorial approach</a> or <a href="/research-desk.html#inquiries">submit a correction</a> with the field, source location and reproducible calculation.</p></section></article></div>
<section class="wrap education-section{reading_class}"><h2>Connect the worksheet to the evidence.</h2><p><a href="/learn-bdc-{lesson}.html">Learn this worksheet’s core concept</a> · <a href="/learn-bdc.html">Study BDCs in four levels</a> · <a href="/bdc-guide.html">Read the BDC field guide</a> · <a href="https://www.benzinga.com/Opinion/26/06/53065817/covered-not-collected-pik-income-and-the-q1-2026-bdc-distribution-stack" target="_blank" rel="noopener">Read the dated PIK research original</a> · <a href="/learn-read-filings.html">Read an issuer filing</a> · <a href="/tools.html">All free calculators</a></p></section>'''
    if kind in ('nii','pik'):
        from filing_labs import cards as filing_cards
        body+=filing_cards(root,sector='bdc')
    return shell(root,tool['slug']+'.html',tool['title'],tool['description'],body,extra='<script src="/vendor/decimal.js/decimal.js" defer></script><script src="/bdc-calculators.js?v=bdc-1.0.2-availability-1" defer></script>')


def outputs(root):
    root=Path(root)
    return {root/(tool['slug']+'.html'):page(root,tool) for tool in TOOLS}
